leep(time.Second) // \u6a21\u62df\u5904\u7406\u65f6\u95f4\n        \n        // \u7b2c\u4e8c\u6b21\u67e5\u8be2\uff0c\u7ed3\u679c\u4fdd\u6301\u4e00\u81f4\n        var users []User\n        tx.Where("age BETWEEN ? AND ?", 18, 25).Find(&users)\n        report.Users = users\n        \n        return nil\n    })\n    \n    return &report, err\n}\n'})}),"\n",(0,a.jsx)(e.h2,{id:"\u4e22\u5931\u66f4\u65b0\u95ee\u9898",children:"\u4e22\u5931\u66f4\u65b0\u95ee\u9898"}),"\n",(0,a.jsx)(e.p,{children:"\u4e22\u5931\u66f4\u65b0\u662f\u6700\u5371\u9669\u7684\u5e76\u53d1\u95ee\u9898\u4e4b\u4e00\uff0c\u7279\u522b\u662f\u5728\u91d1\u878d\u548c\u7535\u5546\u573a\u666f\u4e2d\uff1a"}),"\n",(0,a.jsx)(e.h3,{id:"\u8f6c\u8d26\u573a\u666f\u4e2d\u7684\u4e22\u5931\u66f4\u65b0",children:"\u8f6c\u8d26\u573a\u666f\u4e2d\u7684\u4e22\u5931\u66f4\u65b0"}),"\n",(0,a.jsx)(e.mermaid,{value:"sequenceDiagram\n    participant T1 as \u8f6c\u8d26\u4e8b\u52a11<br/>(A\u2192B 100\u5143)\n    participant T2 as \u8f6c\u8d26\u4e8b\u52a12<br/>(C\u2192A 50\u5143)\n    participant DB as \u6570\u636e\u5e93\n    \n    Note over T1,DB: \u521d\u59cb\u4f59\u989d\uff1aA=1000, B=500, C=300\n    \n    par \u5e76\u53d1\u6267\u884c\n        T1->>DB: BEGIN TRANSACTION\n        T1->>DB: SELECT balance FROM account WHERE id='A'\n        DB--\x3e>T1: \u8fd4\u56de 1000\n    and\n        T2->>DB: BEGIN TRANSACTION  \n        T2->>DB: SELECT balance FROM account WHERE id='A'\n        DB--\x3e>T2: \u8fd4\u56de 1000\n    end\n    \n    T1->>DB: UPDATE account SET balance=900 WHERE id='A'\n    T2->>DB: UPDATE account SET balance=1050 WHERE id='A'\n    \n    par \u63d0\u4ea4\u987a\u5e8f\n        T1->>DB: COMMIT\n    and  \n        T2->>DB: COMMIT (\u8986\u76d6\u4e86T1\u7684\u4fee\u6539)\n    end\n    \n    Note over DB: \u6700\u7ec8A\u4f59\u989d=1050<br/>\u4f46\u5e94\u8be5\u662f950<br/>\u4e22\u5931\u4e86T1\u7684\u6263\u51cf"}),"\n",(0,a.jsx)(e.h3,{id:"\u60b2\u89c2\u9501\u89e3\u51b3\u65b9\u6848",children:"\u60b2\u89c2\u9501\u89e3\u51b3\u65b9\u6848"}),"\n",(0,a.jsx)(e.pre,{children:(0,a.jsx)(e.code,{className:"language-go",children:'type AccountService struct {\n    db *gorm.DB\n}\n\n// \u4f7f\u7528\u60b2\u89c2\u9501\u907f\u514d\u4e22\u5931\u66f4\u65b0\nfunc (s *AccountService) TransferWithPessimisticLock(fromID, toID uint, amount decimal.Decimal) error {\n    return s.db.Transaction(func(tx *gorm.DB) error {\n        var fromAccount, toAccount Account\n        \n        // \u4f7f\u7528 FOR UPDATE \u52a0\u9501\uff0c\u6309ID\u987a\u5e8f\u907f\u514d\u6b7b\u9501\n        lockOrder := []uint{fromID, toID}\n        if fromID > toID {\n            lockOrder = []uint{toID, fromID}\n        }\n        \n        for _, id := range lockOrder {\n            if err := tx.Set("gorm:query_option", "FOR UPDATE").\n                First(&fromAccount, id).Error; err != nil {\n                return err\n            }\n        }\n        \n        // \u68c0\u67e5\u4f59\u989d\n        if fromAccount.Balance.LessThan(amount) {\n            return errors.New("\u4f59\u989d\u4e0d\u8db3")\n        }\n        \n        // \u6267\u884c\u8f6c\u8d26\n        fromAccount.Balance = fromAccount.Balance.Sub(amount)\n        toAccount.Balance = toAccount.Balance.Add(amount)\n        \n        if err := tx.Save(&fromAccount).Error; err != nil {\n            return err\n        }\n        \n        return tx.Save(&toAccount).Error\n    })\n}\n'})}),"\n",(0,a.jsx)(e.h3,{id:"\u4e50\u89c2\u9501\u89e3\u51b3\u65b9\u6848",children:"\u4e50\u89c2\u9501\u89e3\u51b3\u65b9\u6848"}),"\n",(0,a.jsx)(e.pre,{children:(0,a.jsx)(e.code,{className:"language-go",children:'// \u4f7f\u7528\u7248\u672c\u53f7\u5b9e\u73b0\u4e50\u89c2\u9501\ntype Account struct {\n    ID      uint            `gorm:"primaryKey"`\n    UserID  uint            \n    Balance decimal.Decimal \n    Version int64           `gorm:"column:version"` // \u7248\u672c\u53f7\n}\n\nfunc (s *AccountService) TransferWithOptimisticLock(fromID, toID uint, amount decimal.Decimal) error {\n    maxRetries := 3\n    \n    for retry := 0; retry < maxRetries; retry++ {\n        err := s.db.Transaction(func(tx *gorm.DB) error {\n            var fromAccount, toAccount Account\n            \n            // \u8bfb\u53d6\u5f53\u524d\u7248\u672c\n            if err := tx.First(&fromAccount, fromID).Error; err != nil {\n                return err\n            }\n            if err := tx.First(&toAccount, toID).Error; err != nil {\n                return err\n            }\n            \n            originalFromVersion := fromAccount.Version\n            originalToVersion := toAccount.Version\n            \n            // \u68c0\u67e5\u4f59\u989d\n            if fromAccount.Balance.LessThan(amount) {\n                return errors.New("\u4f59\u989d\u4e0d\u8db3")\n            }\n            \n            // \u66f4\u65b0\u4f59\u989d\u548c\u7248\u672c\u53f7\n            fromAccount.Balance = fromAccount.Balance.Sub(amount)\n            fromAccount.Version++\n            toAccount.Balance = toAccount.Balance.Add(amount)\n            toAccount.Version++\n            \n            // \u4f7f\u7528 WHERE \u6761\u4ef6\u786e\u4fdd\u7248\u672c\u53f7\u672a\u53d8\u5316\n            result := tx.Model(&fromAccount).\n                Where("version = ?", originalFromVersion).\n                Updates(map[string]interface{}{\n                    "balance": fromAccount.Balance,\n                    "version": fromAccount.Version,\n                })\n            \n            if result.RowsAffected == 0 {\n                return errors.New("\u5e76\u53d1\u51b2\u7a81\uff0c\u8bf7\u91cd\u8bd5")\n            }\n            \n            result = tx.Model(&toAccount).\n                Where("version = ?", originalToVersion).\n                Updates(map[string]interface{}{\n                    "balance": toAccount.Balance,\n                    "version": toAccount.Version,\n                })\n                \n            if result.RowsAffected == 0 {\n                return errors.New("\u5e76\u53d1\u51b2\u7a81\uff0c\u8bf7\u91cd\u8bd5")\n            }\n            \n            return nil\n        })\n        \n        if err == nil {\n            return nil // \u6210\u529f\n        }\n        \n        if !strings.Contains(err.Error(), "\u5e76\u53d1\u51b2\u7a81") {\n            return err // \u975e\u91cd\u8bd5\u9519\u8bef\n        }\n        \n        // \u6307\u6570\u9000\u907f\n        time.Sleep(time.Duration(retry+1) * 10 * time.Millisecond)\n    }\n    \n    return errors.New("\u91cd\u8bd5\u6b21\u6570\u8d85\u9650")\n}\n'})}),"\n",(0,a.jsx)(e.h2,{id:"\u6b7b\u9501\u68c0\u6d4b\u4e0e\u5904\u7406",children:"\u6b7b\u9501\u68c0\u6d4b\u4e0e\u5904\u7406"}),"\n",(0,a.jsx)(e.p,{children:"MySQL \u7684\u6b7b\u9501\u68c0\u6d4b\u4f7f\u7528 wait-for graph \u7b97\u6cd5\uff1a"}),"\n",(0,a.jsx)(e.mermaid,{value:'graph LR\n    subgraph "\u6b7b\u9501\u573a\u666f"\n        T1[\u4e8b\u52a1T1<br/>\u6301\u6709\u9501A<br/>\u7b49\u5f85\u9501B] \n        T2[\u4e8b\u52a1T2<br/>\u6301\u6709\u9501B<br/>\u7b49\u5f85\u9501A]\n        \n        T1 -.->|\u7b49\u5f85| T2\n        T2 -.->|\u7b49\u5f85| T1\n    end\n    \n    subgraph "\u68c0\u6d4b\u673a\u5236"\n        A[wait-for graph] --\x3e B[\u53d1\u73b0\u73af\u8def]\n        B --\x3e C[\u9009\u62e9\u56de\u6eda\u4ee3\u4ef7\u6700\u5c0f\u7684\u4e8b\u52a1]\n        C --\x3e D[\u91ca\u653e\u8be5\u4e8b\u52a1\u7684\u6240\u6709\u9501]\n        D --\x3e E[\u5176\u4ed6\u4e8b\u52a1\u7ee7\u7eed\u6267\u884c]\n    end'}),"\n",(0,a.jsxs)(e.p,{children:[(0,a.jsx)(e.strong,{children:"Go \u4e2d\u7684\u6b7b\u9501\u9884\u9632\u7b56\u7565"}),"\uff1a"]}),"\n",(0,a.jsx)(e.pre,{children:(0,a.jsx)(e.code,{className:"language-go",children:'// \u7edf\u4e00\u7684\u9501\u987a\u5e8f\u907f\u514d\u6b7b\u9501\nfunc (s *AccountService) TransferSafely(fromID, toID uint, amount decimal.Decimal) error {\n    // \u6309ID\u5927\u5c0f\u6392\u5e8f\uff0c\u4fdd\u8bc1\u9501\u7684\u83b7\u53d6\u987a\u5e8f\u4e00\u81f4\n    firstID, secondID := fromID, toID\n    if fromID > toID {\n        firstID, secondID = toID, fromID\n    }\n    \n    return s.db.Transaction(func(tx *gorm.DB) error {\n        // \u6309\u56fa\u5b9a\u987a\u5e8f\u83b7\u53d6\u9501\n        var first, second Account\n        \n        if err := tx.Set("gorm:query_option", "FOR UPDATE").\n            First(&first, firstID).Error; err != nil {\n            return err\n        }\n        \n        if err := tx.Set("gorm:query_option", "FOR UPDATE").\n            First(&second, secondID).Error; err != nil {\n            return err\n        }\n        \n        // \u6267\u884c\u8f6c\u8d26\u903b\u8f91...\n        return s.doTransfer(tx, fromID, toID, amount)\n    })\n}\n\n// \u8d85\u65f6\u5904\u7406\u907f\u514d\u957f\u65f6\u95f4\u7b49\u5f85\nfunc (s *AccountService) TransferWithTimeout(ctx context.Context, fromID, toID uint, amount decimal.Decimal) error {\n    ctx, cancel := context.WithTimeout(ctx, 5*time.Second)\n    defer cancel()\n    \n    done := make(chan error, 1)\n    \n    go func() {\n        done <- s.TransferSafely(fromID, toID, amount)\n    }()\n    \n    select {\n    case err := <-done:\n        return err\n    case <-ctx.Done():\n        return errors.New("\u8f6c\u8d26\u8d85\u65f6")\n    }\n}\n'})}),"\n",(0,a.jsx)(e.h2,{id:"\u79d2\u6740\u7cfb\u7edf\u5e93\u5b58\u6263\u51cf\u65b9\u6848",children:"\u79d2\u6740\u7cfb\u7edf\u5e93\u5b58\u6263\u51cf\u65b9\u6848"}),"\n",(0,a.jsx)(e.p,{children:"\u9ad8\u5e76\u53d1\u573a\u666f\u4e0b\u7684\u5e93\u5b58\u6263\u51cf\u662f\u4e8b\u52a1\u95ee\u9898\u7684\u5178\u578b\u5e94\u7528\uff1a"}),"\n",(0,a.jsx)(e.mermaid,{value:"sequenceDiagram\n    participant U as \u7528\u6237\u8bf7\u6c42\n    participant API as API\u7f51\u5173\n    participant Cache as Redis\u7f13\u5b58\n    participant Stock as \u5e93\u5b58\u670d\u52a1\n    participant DB as \u6570\u636e\u5e93\n    participant MQ as \u6d88\u606f\u961f\u5217\n    \n    U->>API: \u79d2\u6740\u8bf7\u6c42\n    API->>Cache: \u9884\u68c0\u67e5\u5e93\u5b58\n    \n    alt \u7f13\u5b58\u6709\u5e93\u5b58\n        Cache--\x3e>API: \u5e93\u5b58\u5145\u8db3\n        API->>Stock: \u6263\u51cf\u5e93\u5b58\u8bf7\u6c42\n        \n        Stock->>DB: UPDATE stock SET count=count-1 \n        Note over Stock,DB: WHERE id=? AND count>0\n        \n        alt \u6263\u51cf\u6210\u529f  \n            DB--\x3e>Stock: affected_rows=1\n            Stock->>Cache: \u540c\u6b65\u6263\u51cf\u7f13\u5b58\n            Stock->>MQ: \u53d1\u9001\u8ba2\u5355\u521b\u5efa\u6d88\u606f\n            Stock--\x3e>API: \u6263\u51cf\u6210\u529f\n            API--\x3e>U: \u79d2\u6740\u6210\u529f\n        else \u6263\u51cf\u5931\u8d25\n            DB--\x3e>Stock: affected_rows=0  \n            Stock--\x3e>API: \u5e93\u5b58\u4e0d\u8db3\n            API--\x3e>U: \u79d2\u6740\u5931\u8d25\n        end\n    else \u7f13\u5b58\u65e0\u5e93\u5b58\n        Cache--\x3e>API: \u5e93\u5b58\u4e0d\u8db3\n        API--\x3e>U: \u79d2\u6740\u5931\u8d25\n    end"}),"\n",(0,a.jsxs)(e.p,{children:[(0,a.jsx)(e.strong,{children:"\u5173\u952e\u5b9e\u73b0\u4ee3\u7801"}),"\uff1a"]}),"\n",(0,a.jsx)(e.pre,{children:(0,a.jsx)(e.code,{className:"language-go",children:'type StockService struct {\n    db    *gorm.DB\n    redis *redis.Client\n    mq    MessageQueue\n}\n\nfunc (s *StockService) DeductStock(ctx context.Context, productID uint, quantity int) error {\n    // 1. Redis\u9884\u68c0\u67e5\n    remain, err := s.redis.Get(ctx, fmt.Sprintf("stock:%d", productID)).Int()\n    if err != nil || remain < quantity {\n        return errors.New("\u5e93\u5b58\u4e0d\u8db3")\n    }\n    \n    // 2. \u6570\u636e\u5e93\u539f\u5b50\u6263\u51cf\n    err = s.db.Transaction(func(tx *gorm.DB) error {\n        result := tx.Exec(`\n            UPDATE products \n            SET stock = stock - ? \n            WHERE id = ? AND stock >= ?`,\n            quantity, productID, quantity)\n            \n        if result.Error != nil {\n            return result.Error\n        }\n        \n        if result.RowsAffected == 0 {\n            return errors.New("\u5e93\u5b58\u4e0d\u8db3")\n        }\n        \n        return nil\n    })\n    \n    if err != nil {\n        return err\n    }\n    \n    // 3. \u540c\u6b65\u66f4\u65b0\u7f13\u5b58\n    s.redis.DecrBy(ctx, fmt.Sprintf("stock:%d", productID), int64(quantity))\n    \n    // 4. \u5f02\u6b65\u5904\u7406\u8ba2\u5355\n    orderMsg := OrderMessage{\n        ProductID: productID,\n        Quantity:  quantity,\n        Timestamp: time.Now(),\n    }\n    s.mq.Publish("order.create", orderMsg)\n    \n    return nil\n}\n'})}),"\n",(0,a.jsx)(e.h2,{id:"\u5206\u5e03\u5f0f\u4e8b\u52a1\u5904\u7406",children:"\u5206\u5e03\u5f0f\u4e8b\u52a1\u5904\u7406"}),"\n",(0,a.jsx)(e.p,{children:"\u5728\u5fae\u670d\u52a1\u67b6\u6784\u4e2d\uff0c\u4e8b\u52a1\u95ee\u9898\u53d8\u5f97\u66f4\u52a0\u590d\u6742\uff1a"}),"\n",(0,a.jsx)(e.mermaid,{value:"sequenceDiagram\n    participant Order as \u8ba2\u5355\u670d\u52a1\n    participant Pay as \u652f\u4ed8\u670d\u52a1  \n    participant Stock as \u5e93\u5b58\u670d\u52a1\n    participant Saga as Saga\u534f\u8c03\u5668\n    \n    Note over Order,Saga: Saga\u4e8b\u52a1\u6a21\u5f0f\n    Order->>Saga: \u5f00\u59cb\u5206\u5e03\u5f0f\u4e8b\u52a1\n    Saga->>Order: \u521b\u5efa\u8ba2\u5355\n    Order--\x3e>Saga: \u8ba2\u5355\u521b\u5efa\u6210\u529f\n    \n    Saga->>Stock: \u6263\u51cf\u5e93\u5b58\n    Stock--\x3e>Saga: \u5e93\u5b58\u6263\u51cf\u6210\u529f\n    \n    Saga->>Pay: \u6267\u884c\u652f\u4ed8\n    Pay--\x3e>Saga: \u652f\u4ed8\u5931\u8d25\n    \n    Note over Saga: \u9700\u8981\u8865\u507f\u56de\u6eda\n    Saga->>Stock: \u6062\u590d\u5e93\u5b58(\u8865\u507f)\n    Stock--\x3e>Saga: \u5e93\u5b58\u6062\u590d\u6210\u529f\n    \n    Saga->>Order: \u53d6\u6d88\u8ba2\u5355(\u8865\u507f)\n    Order--\x3e>Saga: \u8ba2\u5355\u53d6\u6d88\u6210\u529f"}),"\n",(0,a.jsxs)(e.p,{children:[(0,a.jsx)(e.strong,{children:"Go \u5b9e\u73b0\u793a\u4f8b"}),"\uff1a"]}),"\n",(0,a.jsx)(e.pre,{children:(0,a.jsx)(e.code,{className:"language-go",children:'type SagaCoordinator struct {\n    steps []SagaStep\n}\n\ntype SagaStep struct {\n    Action      func(ctx context.Context) error\n    Compensate  func(ctx context.Context) error\n    Description string\n}\n\nfunc (s *SagaCoordinator) Execute(ctx context.Context) error {\n    executed := make([]int, 0)\n    \n    // \u6b63\u5411\u6267\u884c\n    for i, step := range s.steps {\n        if err := step.Action(ctx); err != nil {\n            // \u6267\u884c\u8865\u507f\u64cd\u4f5c\n            s.rollback(ctx, executed)\n            return fmt.Errorf("step %d failed: %w", i, err)\n        }\n        executed = append(executed, i)\n    }\n    \n    return nil\n}\n\nfunc (s *SagaCoordinator) rollback(ctx context.Context, executed []int) {\n    // \u9006\u5e8f\u6267\u884c\u8865\u507f\n    for i := len(executed) - 1; i >= 0; i-- {\n        step := s.steps[executed[i]]\n        if err := step.Compensate(ctx); err != nil {\n            // \u8bb0\u5f55\u8865\u507f\u5931\u8d25\uff0c\u9700\u8981\u4eba\u5de5\u4ecb\u5165\n            log.Errorf("compensation failed for step %d: %v", executed[i], err)\n        }\n    }\n}\n'})}),"\n",(0,a.jsx)(e.h2,{id:"\u8bfb\u5199\u5206\u79bb\u67b6\u6784\u4e0b\u7684\u8bfb\u4e00\u81f4\u6027\u6311\u6218",children:"\u8bfb\u5199\u5206\u79bb\u67b6\u6784\u4e0b\u7684\u8bfb\u4e00\u81f4\u6027\u6311\u6218"}),"\n",(0,a.jsx)(e.p,{children:"\u5728\u8bfb\u5199\u5206\u79bb\u67b6\u6784\u4e2d\uff0c\u4e0d\u540c\u9694\u79bb\u7ea7\u522b\u7684\u8bfb\u4e00\u81f4\u6027\u95ee\u9898\u53d8\u5f97\u66f4\u52a0\u590d\u6742\uff0c\u56e0\u4e3a\u6d89\u53ca\u4e3b\u4ece\u590d\u5236\u5ef6\u8fdf\u548c\u6570\u636e\u5206\u5e03\u7684\u95ee\u9898\u3002"}),"\n",(0,a.jsx)(e.h3,{id:"\u8bfb\u5199\u5206\u79bb\u67b6\u6784\u56fe",children:"\u8bfb\u5199\u5206\u79bb\u67b6\u6784\u56fe"}),"\n",(0,a.jsx)(e.mermaid,{value:'graph TB\n    subgraph "\u5e94\u7528\u5c42"\n        App[Go\u5e94\u7528]\n        Router[\u8bfb\u5199\u8def\u7531\u5668]\n    end\n    \n    subgraph "\u6570\u636e\u5e93\u96c6\u7fa4"\n        M